// Transaction Filter Component
// Allows users to filter transactions by:
// - Date range (daily, weekly, monthly, yearly)
// - Transaction type (income, expense)
// - Category

import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './TransactionFilter.css';

function TransactionFilter({ onFilterChange }) {
  const [dateFilter, setDateFilter] = useState('');
  const [typeFilter, setTypeFilter] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('');
  const [categories, setCategories] = useState([]);
  const [loading, setLoading] = useState(false);

  const token = localStorage.getItem('token');

  // Fetch all unique categories when component loads
  useEffect(() => {
    fetchCategories();
  }, []);

  // Fetch categories from backend
  const fetchCategories = async () => {
    try {
      const response = await axios.get(
        'http://localhost:5000/api/filters/categories',
        {
          headers: { Authorization: `Bearer ${token}` }
        }
      );
      setCategories(response.data);
    } catch (error) {
      console.log('Error fetching categories:', error.message);
    }
  };

  // Handle filter changes
  const handleFilterChange = async () => {
    setLoading(true);

    try {
      // Build query parameters
      const params = new URLSearchParams();
      if (dateFilter) params.append('dateFilter', dateFilter);
      if (typeFilter) params.append('typeFilter', typeFilter);
      if (categoryFilter) params.append('categoryFilter', categoryFilter);

      // Fetch filtered transactions
      const response = await axios.get(
        `http://localhost:5000/api/filters?${params.toString()}`,
        {
          headers: { Authorization: `Bearer ${token}` }
        }
      );

      // Pass filtered data to parent component
      onFilterChange(response.data);
    } catch (error) {
      console.log('Error fetching filtered transactions:', error.message);
    } finally {
      setLoading(false);
    }
  };

  // Reset all filters
  const handleReset = () => {
    setDateFilter('');
    setTypeFilter('');
    setCategoryFilter('');
    onFilterChange(null); // Signal parent to fetch all transactions
  };

  // Trigger filter change whenever any filter changes
  useEffect(() => {
    handleFilterChange();
  }, [dateFilter, typeFilter, categoryFilter]);

  return (
    <div className="transaction-filter">
      <h3>🔍 Filter Transactions</h3>

      <div className="filter-controls">
        {/* Date Filter */}
        <div className="filter-group">
          <label>📅 Date Range</label>
          <select
            value={dateFilter}
            onChange={(e) => setDateFilter(e.target.value)}
            className="filter-select"
          >
            <option value="">All Time</option>
            <option value="daily">Today</option>
            <option value="weekly">Last 7 Days</option>
            <option value="monthly">This Month</option>
            <option value="yearly">This Year</option>
          </select>
        </div>

        {/* Type Filter */}
        <div className="filter-group">
          <label>💳 Transaction Type</label>
          <select
            value={typeFilter}
            onChange={(e) => setTypeFilter(e.target.value)}
            className="filter-select"
          >
            <option value="">All Types</option>
            <option value="income">Income</option>
            <option value="expense">Expense</option>
          </select>
        </div>

        {/* Category Filter */}
        <div className="filter-group">
          <label>🏷️ Category</label>
          <select
            value={categoryFilter}
            onChange={(e) => setCategoryFilter(e.target.value)}
            className="filter-select"
          >
            <option value="">All Categories</option>
            {categories.map((category) => (
              <option key={category} value={category}>
                {category}
              </option>
            ))}
          </select>
        </div>

        {/* Reset Button */}
        <button
          onClick={handleReset}
          className="filter-reset-btn"
          disabled={loading}
        >
          🔄 Reset Filters
        </button>
      </div>

      {/* Loading indicator */}
      {loading && <p className="filter-loading">Loading...</p>}

      {/* Active filters display */}
      {(dateFilter || typeFilter || categoryFilter) && (
        <div className="active-filters">
          <p>
            <strong>Active Filters:</strong>
            {dateFilter && <span className="filter-tag">{dateFilter}</span>}
            {typeFilter && <span className="filter-tag">{typeFilter}</span>}
            {categoryFilter && <span className="filter-tag">{categoryFilter}</span>}
          </p>
        </div>
      )}
    </div>
  );
}

export default TransactionFilter;
